-- Fake recipients. Everything here is mock data generated by internal/seed.
CREATE TABLE users (
    id               bigserial     PRIMARY KEY,
    first_name       text          NOT NULL,
    last_name        text          NOT NULL,
    email            text          NOT NULL UNIQUE,
    phone            text          NOT NULL,           -- E.164, e.g. +905321234567
    city             text          NOT NULL,           -- Turkish spelling, e.g. İstanbul
    language         text          NOT NULL CHECK (language IN ('tr', 'en')),
    sms_consent      boolean       NOT NULL,
    email_consent    boolean       NOT NULL,
    order_count      int           NOT NULL DEFAULT 0 CHECK (order_count >= 0),
    total_spent      numeric(12,2) NOT NULL DEFAULT 0 CHECK (total_spent >= 0),
    last_purchase_at timestamptz,
    last_cart_at     timestamptz,                      -- last time items were added to the cart
    signed_up_at     timestamptz   NOT NULL,
    created_at       timestamptz   NOT NULL DEFAULT now()
);

-- A few thousand rows scan in milliseconds, so only the most common filter gets an index.
CREATE INDEX users_city_idx ON users (city);
